import React, { useEffect, useRef, useState } from 'react';
import mapboxgl from 'mapbox-gl';
import * as turf from '@turf/turf';
import { MAPBOX_CONFIG, RoadGraph } from '../config/mapbox.js';

// Set Mapbox access token
mapboxgl.accessToken = MAPBOX_CONFIG.accessToken;

// Snap a point to the nearest road/pathway in the cemetery
function snapToRoad(point, geojson) {
  const roads = geojson.features.filter(f => 
    f.geometry.type === 'LineString' && 
    (f.properties.type === 'main' || f.properties.type === 'pathway')
  );
  
  if (roads.length === 0) return point;
  
  let nearest = null;
  let minDist = Infinity;
  
  roads.forEach(road => {
    const snapped = turf.nearestPointOnLine(road, turf.point(point));
    if (snapped.properties.dist < minDist) {
      minDist = snapped.properties.dist;
      nearest = snapped.geometry.coordinates;
    }
  });
  
  return nearest || point;
}

// Calculate route between two points using the road network
function calculateRoute(startCoords, endCoords, roadGraph, cemeteryData) {
  if (!startCoords || !endCoords || !roadGraph || !cemeteryData) {
    console.warn('Missing required data for routing');
    return null;
  }
  
  // Ensure coordinates are in [lng, lat] format
  const start = Array.isArray(startCoords) ? startCoords : [startCoords.longitude || startCoords.lng, startCoords.latitude || startCoords.lat];
  const end = Array.isArray(endCoords) ? endCoords : [endCoords.longitude || endCoords.lng, endCoords.latitude || endCoords.lat];
  
  // Snap both points to nearest roads
  const startSnapped = snapToRoad(start, cemeteryData);
  const endSnapped = snapToRoad(end, cemeteryData);
  
  console.log('Routing from:', startSnapped, 'to:', endSnapped);
  
  // Try to find path using RoadGraph
  const result = roadGraph.findShortestPath(startSnapped, endSnapped);
  
  if (result && result.path && result.path.length > 0) {
    console.log('✅ Found path with', result.path.length, 'waypoints');
    return {
      waypoints: result.path,
      distance: result.distance || 0
    };
  }
  
  // Fallback: try simple waypoint routing
  console.warn('⚠️ RoadGraph pathfinding failed, trying waypoint routing');
  const waypointRoute = findWaypointRoute(startSnapped, endSnapped, cemeteryData);
  
  if (waypointRoute && waypointRoute.length > 0) {
    console.log('✅ Found waypoint route with', waypointRoute.length, 'waypoints');
    return {
      waypoints: waypointRoute,
      distance: 0
    };
  }
  
  console.error('❌ No valid route found');
  return null;
}

// Simple waypoint routing fallback
function findWaypointRoute(start, end, geojson) {
  const roads = geojson.features.filter(f => 
    f.geometry.type === 'LineString' && 
    (f.properties.type === 'main' || f.properties.type === 'pathway')
  );
  
  if (roads.length === 0) return null;
  
  // Collect all road coordinates
  const waypoints = [];
  roads.forEach(road => {
    if (road.geometry.coordinates) {
      waypoints.push(...road.geometry.coordinates);
    }
  });
  
  if (waypoints.length === 0) return null;
  
  // Find closest waypoints to start and end
  let closestToStart = null;
  let closestToEnd = null;
  let minStartDist = Infinity;
  let minEndDist = Infinity;
  
  waypoints.forEach(waypoint => {
    const startDist = turf.distance(turf.point(start), turf.point(waypoint), { units: 'meters' });
    const endDist = turf.distance(turf.point(end), turf.point(waypoint), { units: 'meters' });
    
    if (startDist < minStartDist) {
      minStartDist = startDist;
      closestToStart = waypoint;
    }
    if (endDist < minEndDist) {
      minEndDist = endDist;
      closestToEnd = waypoint;
    }
  });
  
  if (closestToStart && closestToEnd) {
    return [start, closestToStart, closestToEnd, end];
  }
  
  return null;
}

export default function MapboxMap({ 
  startLot = null, 
  endLot = null, 
  onRouteCalculated = null,
  className = '',
  style = {}
}) {
  const mapContainer = useRef(null);
  const mapRef = useRef(null);
  const roadGraphRef = useRef(null);
  
  const [cemeteryData, setCemeteryData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // Load cemetery data from public folder
  useEffect(() => {
    const loadCemeteryData = async () => {
      try {
        console.log('Loading cemetery data...');
        const response = await fetch('/data/Cemetery .geojson');
        
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        
        const data = await response.json();
        console.log('✅ Cemetery data loaded:', data.features.length, 'features');
        setCemeteryData(data);
        setError(null);
      } catch (err) {
        console.error('❌ Failed to load cemetery data:', err);
        setError(err.message);
      } finally {
        setIsLoading(false);
      }
    };
    
    loadCemeteryData();
  }, []);

  // Initialize map and road graph
  useEffect(() => {
    if (!cemeteryData || mapRef.current) return;

    console.log('Initializing map...');
    
    // Initialize map
    mapRef.current = new mapboxgl.Map({
      container: mapContainer.current,
      style: MAPBOX_CONFIG.defaultMapStyle,
      center: [MAPBOX_CONFIG.defaultViewport.longitude, MAPBOX_CONFIG.defaultViewport.latitude],
      zoom: MAPBOX_CONFIG.defaultViewport.zoom,
      projection: 'mercator'
    });

    // Build road graph
    try {
      roadGraphRef.current = new RoadGraph(cemeteryData);
      console.log('✅ Road graph built successfully');
    } catch (err) {
      console.error('❌ Failed to build road graph:', err);
      setError('Failed to build road network');
    }

    // Add route layer when map loads
    mapRef.current.on('load', () => {
      console.log('Map loaded, adding route layer...');
      
      // Add route source
      if (!mapRef.current.getSource('route')) {
        mapRef.current.addSource('route', {
          type: 'geojson',
          data: {
            type: 'Feature',
            geometry: { type: 'LineString', coordinates: [] }
          }
        });

        // Add route layer
        mapRef.current.addLayer({
          id: 'route-layer',
          type: 'line',
          source: 'route',
          layout: {
            'line-cap': 'round',
            'line-join': 'round'
          },
          paint: {
            'line-color': '#0074D9',
            'line-width': 4,
            'line-opacity': 0.8
          }
        });
        
        console.log('✅ Route layer added');
      }
    });

    // Add error handling
    mapRef.current.on('error', (e) => {
      console.error('Map error:', e);
      setError('Map failed to load');
    });

  }, [cemeteryData]);

  // Calculate and display route when start/end lots change
  useEffect(() => {
    if (!mapRef.current || !roadGraphRef.current || !cemeteryData) return;
    if (!startLot || !endLot) {
      // Clear route if no start/end lots
      if (mapRef.current.getSource('route')) {
        mapRef.current.getSource('route').setData({
          type: 'Feature',
          geometry: { type: 'LineString', coordinates: [] }
        });
      }
      return;
    }

    console.log('Calculating route between lots...');
    
    const route = calculateRoute(
      startLot.coordinates || startLot,
      endLot.coordinates || endLot,
      roadGraphRef.current,
      cemeteryData
    );

    if (route && route.waypoints && route.waypoints.length > 0) {
      console.log('✅ Route calculated, displaying on map');
      
      // Update route on map
      mapRef.current.getSource('route').setData({
        type: 'Feature',
        geometry: {
          type: 'LineString',
          coordinates: route.waypoints
        }
      });
      
      // Notify parent component
      if (onRouteCalculated) {
        onRouteCalculated(route);
      }
    } else {
      console.warn('⚠️ No route found, clearing map');
      
      // Clear route
      mapRef.current.getSource('route').setData({
        type: 'Feature',
        geometry: { type: 'LineString', coordinates: [] }
      });
    }
  }, [startLot, endLot, cemeteryData, onRouteCalculated]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
      }
    };
  }, []);

  // Loading state
  if (isLoading) {
    return (
      <div className={`mapbox-container loading ${className}`} style={style}>
        <div style={{ 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'center',
          height: '100%',
          backgroundColor: '#f5f5f5',
          borderRadius: '8px'
        }}>
          <div>Loading cemetery data...</div>
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className={`mapbox-container error ${className}`} style={style}>
        <div style={{ 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'center',
          height: '100%',
          backgroundColor: '#f8d7da',
          color: '#721c24',
          borderRadius: '8px',
          padding: '20px',
          textAlign: 'center'
        }}>
          <div>
            <div>❌ Error loading map</div>
            <div style={{ fontSize: '0.9em', marginTop: '10px' }}>{error}</div>
          </div>
        </div>
      </div>
    );
  }

  // Main map component
  return (
    <div className={`mapbox-container ${className}`} style={style}>
      <div
        ref={mapContainer}
        style={{ 
          width: '100%', 
          height: '100%', 
          borderRadius: '8px',
          minHeight: '400px'
        }}
      />
    </div>
  );
}