import React, { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { AuthContext } from '../context/AuthContext';
import eventBus, { EVENTS } from '../utils/eventBus';
import MapboxMap from '../components/MapboxMap';
import CreateLotModal from '../components/CreateLotModal';
import GraveLocator from '../components/GraveLocator';
import './MapboxMapView.css';

export default function MapboxMapView() {
  const { token, role } = useContext(AuthContext);
  const [lots, setLots] = useState([]);
  const [selectedLot, setSelectedLot] = useState(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [clickedPosition, setClickedPosition] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  // Add error timeout cleanup
  useEffect(() => {
    let errorTimeout;
    if (error) {
      errorTimeout = setTimeout(() => {
        setError(null);
      }, 5000);
    }
    return () => {
      if (errorTimeout) {
        clearTimeout(errorTimeout);
      }
    };
  }, [error]);

  // Garden polygon coordinates (exact from your GeoJSON data)
  const gardenPolygons = {
    'A': [
      [121.069415, 14.53879],
      [121.069888, 14.538776],
      [121.069876, 14.538393],
      [121.069403, 14.538394],
      [121.069415, 14.53879] // Close the polygon
    ],
    'B': [
      [121.069928, 14.538777],
      [121.070611, 14.538762],
      [121.070609, 14.538391],
      [121.069919, 14.53839],
      [121.069928, 14.538777] // Close the polygon
    ],
    'C': [
      [121.070769, 14.538362],
      [121.071787, 14.538341],
      [121.07189, 14.538103],
      [121.070762, 14.53812],
      [121.070769, 14.538362] // Close the polygon
    ]
  };

  // Point-in-polygon test using ray casting algorithm
  const pointInPolygon = (point, polygon) => {
    const [x, y] = point;
    let inside = false;
    
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      const [xi, yi] = polygon[i];
      const [xj, yj] = polygon[j];
      
      if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) {
        inside = !inside;
      }
    }
    
    return inside;
  };

  // Filter graves that are outside garden polygon
  const filterGravesWithinBounds = (graves, garden) => {
    const polygon = gardenPolygons[garden];
    if (!polygon) return graves;
    
    // Calculate garden bounds for positioning
    const minLng = Math.min(...polygon.map(p => p[0]));
    const maxLng = Math.max(...polygon.map(p => p[0]));
    const minLat = Math.min(...polygon.map(p => p[1]));
    const maxLat = Math.max(...polygon.map(p => p[1]));
    
    const gardenWidth = maxLng - minLng;
    const gardenHeight = maxLat - minLat;
    
    // Real standard grave dimensions (1m × 2m)
    const standardGraveWidth = 0.00000465; // 1m in degrees longitude
    const standardGraveLength = 0.000009;  // 2m in degrees latitude
    
    // Calculate how many graves can fit with standard size
    const maxColumns = Math.floor(gardenWidth / standardGraveWidth);
    const maxRows = Math.floor(gardenHeight / standardGraveLength);
    
    // Use the actual data range to calculate grave size
    const actualRows = Math.max(...graves.map(g => g.row || 0));
    const actualColumns = Math.max(...graves.map(g => g.column || 0));
    const usedRows = Math.min(actualRows, maxRows);
    const usedColumns = Math.min(actualColumns, maxColumns);
    
    const actualGraveWidth = gardenWidth / usedColumns;
    const actualGraveLength = gardenHeight / usedRows;
    
    return graves.filter(grave => {
      const row = grave.row;
      const column = grave.column;
      
      if (!row || !column) return false;
      
      // Calculate grave center position
      const offsetLng = (column - 1) * actualGraveWidth;
      const offsetLat = (row - 1) * actualGraveLength;
      
      const graveCenterLng = minLng + offsetLng + (actualGraveWidth / 2);
      const graveCenterLat = minLat + offsetLat + (actualGraveLength / 2);
      
      // Check if the grave center is within the garden polygon
      const isWithinPolygon = pointInPolygon([graveCenterLng, graveCenterLat], polygon);
      
      if (!isWithinPolygon) {
        console.warn(`Grave ${grave.id} (row ${row}, col ${column}) is outside garden ${garden} polygon - HIDING`);
      }
      
      return isWithinPolygon;
    });
  };

  // Fetch graves from all gardens
  const fetchLots = async () => {
    try {
      setLoading(true);
      const allGraves = [];
      
      // Fetch graves from all three gardens
      const gardens = ['A', 'B', 'C'];
      for (const garden of gardens) {
        try {
          const response = await axios.get(
            `${process.env.REACT_APP_API_URL}/admin/graves/garden/${garden}`,
            { headers: { Authorization: `Bearer ${token}` } }
          );
          
          // Convert grave data to map-compatible format
          const graves = response.data.graves.map(grave => ({
            _id: grave._id,
            id: grave.id,
            name: grave.name || '',
            birth: grave.birth || '',
            death: grave.death || '',
            status: grave.status,
            // Keep the original coordinates structure for rectangle rendering
            coordinates: grave.coordinates,
            // Add grave-specific data
            garden: grave.garden,
            row: grave.row,
            column: grave.column,
            location: grave.location,
            price: grave.price,
            sqm: grave.sqm,
            // Keep bounds for backward compatibility with popup positioning
            bounds: grave.coordinates ? [
              [grave.coordinates.coordinates[1] - 0.000009, grave.coordinates.coordinates[0] - 0.00000465], // [lat, lng] - southwest
              [grave.coordinates.coordinates[1] + 0.000009, grave.coordinates.coordinates[0] + 0.00000465]  // [lat, lng] - northeast
            ] : [[0, 0], [0, 0]]
          }));
          
          // Filter out graves that are outside garden bounds
          const filteredGraves = filterGravesWithinBounds(graves, garden);
          console.log(`Admin Map Garden ${garden}: ${graves.length} total graves, ${filteredGraves.length} within bounds`);
          
          allGraves.push(...filteredGraves);
        } catch (gardenErr) {
          console.warn(`Failed to fetch graves from Garden ${garden}:`, gardenErr);
        }
      }
      
      setLots(allGraves);
      setLoading(false);
    } catch (err) {
      console.error('Failed to fetch graves:', err);
      setError('Failed to load graves from server');
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLots();

    // Subscribe to lot events
    const handleLotUpdate = () => fetchLots();
    eventBus.on(EVENTS.LOT_UPDATED, handleLotUpdate);
    eventBus.on(EVENTS.LOT_CREATED, handleLotUpdate);
    eventBus.on(EVENTS.LOT_DELETED, handleLotUpdate);
    eventBus.on(EVENTS.RESERVATION_CHANGED, handleLotUpdate);

    return () => {
      eventBus.off(EVENTS.LOT_UPDATED, handleLotUpdate);
      eventBus.off(EVENTS.LOT_CREATED, handleLotUpdate);
      eventBus.off(EVENTS.LOT_DELETED, handleLotUpdate);
      eventBus.off(EVENTS.RESERVATION_CHANGED, handleLotUpdate);
    };
  }, [token]);


  const handleLotClick = (lot) => {
    setSelectedLot(lot);
  };

  const handleCreateLot = async (lotData) => {
    try {
      const [lat, lng] = clickedPosition;
      
      // Create bounds around the clicked position
      const bounds = [
        [lat - 0.00025, lng - 0.00025],
        [lat + 0.00025, lng + 0.00025]
      ];

      const requestData = {
        ...lotData,
        bounds
      };

      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/staff/lots`,
        requestData,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setLots([...lots, response.data]);
      setShowCreateModal(false);
      setClickedPosition(null);
      eventBus.emit(EVENTS.LOT_CREATED, response.data);
    } catch (err) {
      console.error('Failed to create lot:', err.response?.data || err);
      setError(`Failed to create lot: ${err.response?.data?.msg || err.message}`);
    }
  };

  const handleEditLot = async (lotData) => {
    try {
      const updatedLotData = {
        ...lotData,
        bounds: selectedLot.bounds
      };

      const response = await axios.put(
        `${process.env.REACT_APP_API_URL}/staff/lots/${selectedLot._id}`,
        updatedLotData,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setLots(lots.map(lot => 
        lot._id === selectedLot._id ? { ...response.data, bounds: selectedLot.bounds } : lot
      ));
      setSelectedLot(null);
      setShowCreateModal(false);
      eventBus.emit(EVENTS.LOT_UPDATED, response.data);
    } catch (err) {
      console.error('Failed to update lot:', err);
      setError('Failed to update lot');
    }
  };

  const handleDeleteLot = async (lotId) => {
    if (!lotId) {
      setError('Cannot delete lot: Invalid ID');
      return;
    }

    try {
      const simpleId = lotId.split('/').pop().split('_').pop();
      
      await axios.delete(
        `${process.env.REACT_APP_API_URL}/staff/lots/${simpleId}`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      
      setLots(lots.filter(lot => lot._id !== lotId && lot.id !== lotId));
      setSelectedLot(null);
      setShowCreateModal(false);
      setError(null);
      eventBus.emit(EVENTS.LOT_DELETED, lotId);
    } catch (err) {
      console.error('Failed to delete lot:', err);
      setError(`Failed to delete lot: ${err.response?.data?.message || err.message}`);
    }
  };

  const handleCloseModal = () => {
    setShowCreateModal(false);
    setSelectedLot(null);
    setClickedPosition(null);
  };

  if (loading) {
    return (
      <div className="mapbox-map-view loading">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Loading cemetery map...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mapbox-map-view">
      {/* Header with controls */}
      <div className="map-header">
        <div className="map-title">
          <h2>Cemetery Map</h2>
          <p>Interactive map showing all lots and landmarks</p>
        </div>
        
      </div>

      {/* Error message */}
      {error && (
        <div className="error-message">
          <span>⚠️ {error}</span>
          <button onClick={() => setError(null)}>×</button>
        </div>
      )}

      {/* Map container */}
      <div className="map-container">
        <MapboxMap
          lots={lots}
          selectedLot={selectedLot}
          onLotClick={handleLotClick}
          showRoads={true}
          showColumbarium={true}
        />
        
        {/* Grave Locator Overlay */}
        <div className="grave-locator-overlay">
          <GraveLocator
            lots={lots}
            onSelect={(lot) => {
              setSelectedLot(lot);
              // Center map on selected lot
              if (lot.bounds) {
                const centerLat = (lot.bounds[0][0] + lot.bounds[1][0]) / 2;
                const centerLng = (lot.bounds[0][1] + lot.bounds[1][1]) / 2;
                // This will be handled by the map component
              }
            }}
            onNavigate={(startLot, endLot) => {
              // Handle navigation between lots using simplified routing
              console.log('Navigate from', startLot, 'to', endLot);
              // This will be handled by the MapboxMap component's simplified routing
            }}
          />
        </div>
      </div>


      {/* Create/Edit Lot Modal */}
      {showCreateModal && (
        <CreateLotModal
          show={showCreateModal}
          onClose={handleCloseModal}
          onSave={selectedLot ? handleEditLot : handleCreateLot}
          onDelete={selectedLot ? () => handleDeleteLot(selectedLot._id) : null}
          initialLot={selectedLot}
          position={clickedPosition}
        />
      )}
    </div>
  );
}

