import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import { AuthContext } from '../context/AuthContext';
import { FaFilter } from 'react-icons/fa';
import './GraveManagement.css';

const API_BASE_URL = process.env.REACT_APP_API_URL || '/api';

export default function GraveManagement() {
  const { token, role } = useContext(AuthContext);
  const [gardens, setGardens] = useState({});
  const [selectedGarden, setSelectedGarden] = useState('A');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');


  useEffect(() => {
    if (token && role === 'admin') {
      fetchGardenConfig();
      fetchGardenData(selectedGarden);
    } else if (!token) {
      setError('Please log in to access grave management');
      setLoading(false);
    } else if (role !== 'admin') {
      setError('Admin access required for grave management');
      setLoading(false);
    }
  }, [selectedGarden, token, role]);

  const fetchGardenConfig = async () => {
    try {
      const response = await axios.get(`${API_BASE_URL}/admin/graves/config`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setGardens(response.data);
    } catch (err) {
      console.error('Error fetching garden config:', err);
      setError('Failed to load garden configuration');
    }
  };

  // Garden polygon coordinates (loaded from your actual GeoJSON data)
  const [gardenPolygons, setGardenPolygons] = useState({
    'A': [
      [121.069415, 14.53879],
      [121.069888, 14.538776],
      [121.069876, 14.538393],
      [121.069403, 14.538394],
      [121.069415, 14.53879] // Close the polygon
    ],
    'B': [
      [121.069928, 14.538777],
      [121.070611, 14.538762],
      [121.070609, 14.538391],
      [121.069919, 14.53839],
      [121.069928, 14.538777] // Close the polygon
    ],
    'C': [
      [121.070769, 14.538362],
      [121.071787, 14.538341],
      [121.07189, 14.538103],
      [121.070762, 14.53812],
      [121.070769, 14.538362] // Close the polygon
    ]
  });

  // Load garden polygons from your actual GeoJSON data
  useEffect(() => {
    const loadGardenPolygons = async () => {
      try {
        const response = await fetch('/data/Cemetery .geojson');
        if (response.ok) {
          const geoJsonData = await response.json();
          const gardenFeatures = geoJsonData.features.filter(feature => 
            feature.properties.type === 'garden'
          );
          
          const newGardenPolygons = {};
          gardenFeatures.forEach(feature => {
            const gardenId = feature.properties.id.split('-')[1].toUpperCase(); // garden-a -> A
            newGardenPolygons[gardenId] = feature.geometry.coordinates[0];
          });
          
          setGardenPolygons(newGardenPolygons);
          console.log('Loaded garden polygons from your GeoJSON:', newGardenPolygons);
        }
      } catch (error) {
        console.error('Failed to load garden polygons from GeoJSON:', error);
      }
    };
    
    loadGardenPolygons();
  }, []);

  // Point-in-polygon test using ray casting algorithm
  const pointInPolygon = (point, polygon) => {
    const [x, y] = point;
    let inside = false;
    
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      const [xi, yi] = polygon[i];
      const [xj, yj] = polygon[j];
      
      if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) {
        inside = !inside;
      }
    }
    
    return inside;
  };

  // Hardcoded list of graves that should be disabled (outside garden bounds)
  const disabledGraves = {
    'A': [
      // Add specific grave IDs that are outside Garden A bounds
      // Format: 'A-row-column' (e.g., 'A-15-23')
    ],
    'B': [
      // Add specific grave IDs that are outside Garden B bounds
    ],
    'C': [
      // Add specific grave IDs that are outside Garden C bounds
    ]
  };

  // Filter graves that fall outside garden polygon
  const filterGravesWithinBounds = (graves, garden) => {
    const polygon = gardenPolygons[garden];
    if (!polygon) return graves;

    console.log(`Garden ${garden} polygon:`, polygon);
    
    // Calculate garden bounds for grave positioning
    const minLng = Math.min(...polygon.map(p => p[0]));
    const maxLng = Math.max(...polygon.map(p => p[0]));
    const minLat = Math.min(...polygon.map(p => p[1]));
    const maxLat = Math.max(...polygon.map(p => p[1]));
    
    const gardenWidth = maxLng - minLng;
    const gardenHeight = maxLat - minLat;
    
    // Real standard grave dimensions (1m × 2m)
    const standardGraveWidth = 0.00000465; // 1m in degrees longitude
    const standardGraveLength = 0.000009;  // 2m in degrees latitude
    
    // Calculate how many graves can fit with standard size
    const maxColumns = Math.floor(gardenWidth / standardGraveWidth);
    const maxRows = Math.floor(gardenHeight / standardGraveLength);
    
    console.log(`Garden ${garden} bounds: minLng=${minLng.toFixed(6)}, maxLng=${maxLng.toFixed(6)}, minLat=${minLat.toFixed(6)}, maxLat=${maxLat.toFixed(6)}`);
    console.log(`Garden ${garden} dimensions: ${gardenWidth.toFixed(6)} x ${gardenHeight.toFixed(6)} degrees`);
    console.log(`Garden ${garden} max capacity: ${maxRows} rows x ${maxColumns} columns`);
    
    // Use the theoretical maximum capacity to ensure graves stay within bounds
    const usedRows = maxRows;
    const usedColumns = maxColumns;
    
    const actualGraveWidth = gardenWidth / usedColumns;
    const actualGraveLength = gardenHeight / usedRows;

    console.log(`Garden ${garden} actual grave size: ${actualGraveWidth.toFixed(8)} x ${actualGraveLength.toFixed(8)} degrees`);

    // Don't filter - just mark graves outside bounds as disabled
    return graves.map(grave => {
      const row = grave.row;
      const column = grave.column;
      
      if (!row || !column) {
        console.log(`Grave ${grave.id} missing row/column data`);
        return { ...grave, disabled: true, reason: 'Missing row/column' };
      }
      
      // Check if this grave is in the hardcoded disabled list
      if (disabledGraves[garden] && disabledGraves[garden].includes(grave.id)) {
        console.log(`Grave ${grave.id} is in disabled list - DISABLING`);
        return { ...grave, disabled: true, reason: 'Manually disabled (outside bounds)' };
      }
      
      // Calculate grave center position
      const offsetLng = (column - 1) * actualGraveWidth;
      const offsetLat = (row - 1) * actualGraveLength;
      
      const graveCenterLng = minLng + offsetLng + (actualGraveWidth / 2);
      const graveCenterLat = minLat + offsetLat + (actualGraveLength / 2);
      
      // Check if the grave center is within the garden polygon
      const isWithinPolygon = pointInPolygon([graveCenterLng, graveCenterLat], polygon);
      
      if (!isWithinPolygon) {
        console.warn(`Grave ${grave.id} (row ${row}, col ${column}) is outside garden ${garden} polygon - DISABLING in management`);
        console.log(`  Grave center: (${graveCenterLng.toFixed(6)}, ${graveCenterLat.toFixed(6)})`);
        return { ...grave, disabled: true, reason: 'Outside garden polygon' };
      }
      
      return { ...grave, disabled: false };
    });
  };

  const fetchGardenData = async (garden) => {
    try {
      setLoading(true);
      const response = await axios.get(`${API_BASE_URL}/admin/graves/garden/${garden}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      // Filter out graves that fall outside the garden bounds
      const filteredGraves = filterGravesWithinBounds(response.data.graves, garden);
      const filteredData = {
        ...response.data,
        graves: filteredGraves
      };
      
      const disabledCount = filteredGraves.filter(g => g.disabled).length;
      console.log(`Garden ${garden}: ${response.data.graves.length} total graves, ${disabledCount} disabled (outside bounds)`);
      setGardenData(filteredData);
    } catch (err) {
      console.error('Error fetching garden data:', err);
      setError('Failed to load garden data');
    } finally {
      setLoading(false);
    }
  };

  const [gardenData, setGardenData] = useState(null);
  const [showGardenSelector, setShowGardenSelector] = useState(false);
  const [selectedGrave, setSelectedGrave] = useState(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editForm, setEditForm] = useState({
    name: '',
    birth: '',
    death: '',
    status: 'available'
  });
  const [hoveredGrave, setHoveredGrave] = useState(null);
  const [tooltipPosition, setTooltipPosition] = useState({ x: 0, y: 0 });


  const handleGardenSelect = (garden) => {
    setSelectedGarden(garden);
    setShowGardenSelector(false); // Close the selector after selection
  };

  const handleGraveClick = (grave) => {
    setSelectedGrave(grave);
  };

  const handleGraveMouseEnter = (grave, event) => {
    setHoveredGrave(grave);
    setTooltipPosition({
      x: event.clientX + 10,
      y: event.clientY - 10
    });
  };

  const handleGraveMouseLeave = () => {
    setHoveredGrave(null);
  };

  const handleEditClick = () => {
    if (selectedGrave) {
      setEditForm({
        name: selectedGrave.name || '',
        birth: selectedGrave.birth || '',
        death: selectedGrave.death || '',
        status: selectedGrave.status || 'available'
      });
      setShowEditModal(true);
    }
  };

  const handleEditFormChange = (field, value) => {
    setEditForm(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleSaveEdit = async () => {
    if (!selectedGrave) return;

    try {
      const response = await axios.put(
        `${API_BASE_URL}/admin/graves/${selectedGrave._id}`,
        {
          name: editForm.name,
          birth: editForm.birth,
          death: editForm.death,
          status: editForm.status
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      // Update the selected grave with new data
      setSelectedGrave(prev => ({
        ...prev,
        name: editForm.name,
        birth: editForm.birth,
        death: editForm.death,
        status: editForm.status
      }));

      // Update the grave in gardenData
      setGardenData(prev => ({
        ...prev,
        graves: prev.graves.map(grave => 
          grave._id === selectedGrave._id 
            ? { ...grave, name: editForm.name, birth: editForm.birth, death: editForm.death, status: editForm.status }
            : grave
        )
      }));

      setShowEditModal(false);
      console.log('Grave updated successfully');
    } catch (err) {
      console.error('Error updating grave:', err);
      setError('Failed to update grave');
    }
  };

  const handleCancelEdit = () => {
    setShowEditModal(false);
    setEditForm({
      name: '',
      birth: '',
      death: '',
      status: 'available'
    });
  };


  const handleBulkOperation = async (operation, data = {}) => {
    try {
      setLoading(true);
      const response = await axios.post(`${API_BASE_URL}/admin/graves/bulk`, {
        operation,
        garden: selectedGarden,
        data
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      // Refresh garden data
      await fetchGardenData(selectedGarden);
      
      alert(response.data.message);
    } catch (err) {
      console.error('Error in bulk operation:', err);
      setError('Bulk operation failed');
    } finally {
      setLoading(false);
    }
  };

  const handleGraveStatusChange = async (graveId, newStatus) => {
    try {
      await axios.put(`${API_BASE_URL}/admin/graves/${graveId}`, {
        status: newStatus
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      // Refresh garden data
      await fetchGardenData(selectedGarden);
    } catch (err) {
      console.error('Error updating grave status:', err);
      setError('Failed to update grave status');
    }
  };

  if (loading && !gardenData) {
    return <div className="loading-spinner">Loading grave management...</div>;
  }

  return (
    <div className="grave-management">
      <div className="grave-management-header">
        <h1>Grave Management System</h1>
        <p>Manage graves across all gardens with row/column organization</p>
      </div>

      {error && <div className="error-banner">{error}</div>}

      {/* Garden Selection */}
      <div className="garden-selector">
        <div className="garden-selector-header">
          <button 
            className="btn btn-outline"
            onClick={() => setShowGardenSelector(!showGardenSelector)}
          >
            <FaFilter /> {showGardenSelector ? 'Hide' : 'Select'} Garden
          </button>
        </div>

        {showGardenSelector && (
          <div className="garden-dropdown">
            <label>Garden:</label>
            <select 
              className="filter-select"
              value={selectedGarden}
              onChange={(e) => handleGardenSelect(e.target.value)}
            >
              {Object.entries(gardens).map(([garden, config]) => (
                <option key={garden} value={garden}>
                  {config.name}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>

      {/* Garden Overview */}
      {gardenData && (
        <div className="garden-overview">
          <div className="garden-info">
            <h2>{gardenData.garden.name}</h2>
            <p>Grid: {gardenData.garden.rows} rows × {gardenData.garden.columns} columns</p>
            <p>Capacity: {gardenData.garden.totalGraves} graves</p>
          </div>

          <div className="garden-statistics">
            <div className="stat-card available">
              <span className="stat-number">{gardenData.statistics.available}</span>
              <span className="stat-label">Available</span>
            </div>
            <div className="stat-card occupied">
              <span className="stat-number">{gardenData.statistics.occupied}</span>
              <span className="stat-label">Occupied</span>
            </div>
            <div className="stat-card reserved">
              <span className="stat-number">{gardenData.statistics.reserved}</span>
              <span className="stat-label">Reserved</span>
            </div>
            <div className="stat-card maintenance">
              <span className="stat-number">{gardenData.statistics.maintenance}</span>
              <span className="stat-label">Maintenance</span>
            </div>
          </div>
        </div>
      )}


      {/* Bulk Operations */}
      <div className="bulk-operations">
        <h3>Bulk Operations</h3>
        <div className="bulk-buttons">
          <button
            className="btn btn-primary"
            onClick={() => handleBulkOperation('createGrid')}
            disabled={loading}
          >
            Create Garden Grid
          </button>
          <button
            className="btn btn-warning"
            onClick={() => {
              if (window.confirm('Are you sure you want to clear all graves in this garden?')) {
                handleBulkOperation('clearGarden');
              }
            }}
            disabled={loading}
          >
            Clear Garden
          </button>
        </div>
      </div>

      {/* Grave Grid */}
      {gardenData && (
        <div className="grave-grid-container">
          <h3>Grave Grid - {gardenData.garden.name}</h3>
          <GraveGrid
            garden={gardenData.garden}
            graves={gardenData.graves}
            onStatusChange={handleGraveStatusChange}
            onGraveClick={handleGraveClick}
            onGraveMouseEnter={handleGraveMouseEnter}
            onGraveMouseLeave={handleGraveMouseLeave}
            loading={loading}
          />
        </div>
      )}

      {/* Grave Info Tooltip */}
      {(hoveredGrave || selectedGrave) && (
        <div 
          className="custom-tooltip"
          style={{
            position: 'fixed',
            left: selectedGrave ? tooltipPosition.x : tooltipPosition.x,
            top: selectedGrave ? tooltipPosition.y : tooltipPosition.y,
            zIndex: 1000,
            pointerEvents: selectedGrave ? 'auto' : 'none'
          }}
        >
          <div className="tooltip-content">
            <div className="tooltip-header">
              <strong>{(selectedGrave || hoveredGrave).id}</strong> - {(selectedGrave || hoveredGrave).status.toUpperCase()}
            </div>
            {(selectedGrave || hoveredGrave).name && <div>Name: {(selectedGrave || hoveredGrave).name}</div>}
            {(selectedGrave || hoveredGrave).birth && <div>Birth: {(selectedGrave || hoveredGrave).birth}</div>}
            {(selectedGrave || hoveredGrave).death && <div>Death: {(selectedGrave || hoveredGrave).death}</div>}
            <div>Location: {(selectedGrave || hoveredGrave).location || 'Not specified'}</div>
            <div>Price: ₱{(selectedGrave || hoveredGrave).price || 'Not specified'}</div>
            {selectedGrave && <div>Size: {selectedGrave.sqm || 'Not specified'} sqm</div>}
            
            {/* Edit button only shows when grave is selected (clicked) */}
            {selectedGrave && (
              <div className="tooltip-actions">
                <button className="btn btn-primary btn-small" onClick={handleEditClick}>
                  Edit
                </button>
                <button className="btn btn-secondary btn-small" onClick={() => setSelectedGrave(null)}>
                  Close
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Edit Modal */}
      {showEditModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h3>Edit Grave - {selectedGrave?.id}</h3>
              <button className="modal-close" onClick={handleCancelEdit}>×</button>
            </div>
            <div className="modal-body">
              <div className="form-group">
                <label>Name:</label>
                <input
                  type="text"
                  value={editForm.name}
                  onChange={(e) => handleEditFormChange('name', e.target.value)}
                  placeholder="Enter name"
                />
              </div>
              <div className="form-group">
                <label>Birth Date:</label>
                <input
                  type="date"
                  value={editForm.birth}
                  onChange={(e) => handleEditFormChange('birth', e.target.value)}
                />
              </div>
              <div className="form-group">
                <label>Death Date:</label>
                <input
                  type="date"
                  value={editForm.death}
                  onChange={(e) => handleEditFormChange('death', e.target.value)}
                />
              </div>
              <div className="form-group">
                <label>Status:</label>
                <select
                  value={editForm.status}
                  onChange={(e) => handleEditFormChange('status', e.target.value)}
                >
                  <option value="available">Available</option>
                  <option value="occupied">Occupied</option>
                  <option value="reserved">Reserved</option>
                  <option value="maintenance">Maintenance</option>
                  <option value="unavailable">Unavailable</option>
                </select>
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-primary" onClick={handleSaveEdit}>
                Save Changes
              </button>
              <button className="btn btn-secondary" onClick={handleCancelEdit}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// Grave Grid Component
function GraveGrid({ garden, graves, onStatusChange, onGraveClick, onGraveMouseEnter, onGraveMouseLeave, loading }) {
  const [selectedGraves, setSelectedGraves] = useState(new Set());

  // Fixed color configuration
  const getStatusColor = (status) => {
    const colors = {
      available: '#34c759',
      occupied: '#8e8e93',
      reserved: '#007bff',
      maintenance: '#ff9500',
      unavailable: '#ff3b30'
    };
    return colors[status] || '#8e8e93';
  };

  // Create a map of graves by position
  const graveMap = {};
  graves.forEach(grave => {
    graveMap[`${grave.row}-${grave.column}`] = grave;
  });
  

  const handleGraveClick = (row, column) => {
    const graveId = `${garden.name.split(' ')[1]}-${row}-${column}`;
    const grave = graveMap[`${row}-${column}`];
    
    if (grave) {
      // Cycle through statuses
      const statuses = ['available', 'occupied', 'reserved', 'maintenance', 'unavailable'];
      const currentIndex = statuses.indexOf(grave.status);
      const nextStatus = statuses[(currentIndex + 1) % statuses.length];
      
      onStatusChange(graveId, nextStatus);
    }
  };

  const handleGraveSelect = (row, column) => {
    const key = `${row}-${column}`;
    setSelectedGraves(prev => {
      const newSet = new Set(prev);
      if (newSet.has(key)) {
        newSet.delete(key);
      } else {
        newSet.add(key);
      }
      return newSet;
    });
  };

  const renderGrave = (row, column) => {
    const grave = graveMap[`${row}-${column}`];
    const isSelected = selectedGraves.has(`${row}-${column}`);
    
    if (grave) {
      const isDisabled = grave.disabled;
      
      // Create tooltip content
      const tooltipContent = isDisabled 
        ? `${grave.id} - DISABLED (${grave.reason})`
        : `${grave.id} - ${grave.status.toUpperCase()}${grave.name ? `\nName: ${grave.name}` : ''}${grave.birth ? `\nBirth: ${grave.birth}` : ''}${grave.death ? `\nDeath: ${grave.death}` : ''}`;
      
      
      return (
        <div
          key={`${row}-${column}`}
          className={`grave-cell ${grave.status} ${isSelected ? 'selected' : ''} ${isDisabled ? 'disabled' : ''}`}
          style={{ 
            backgroundColor: isDisabled ? '#f0f0f0' : getStatusColor(grave.status),
            opacity: isDisabled ? 0.5 : 1,
            cursor: isDisabled ? 'not-allowed' : 'pointer'
          }}
          onClick={() => {
            if (!isDisabled) {
              onGraveClick(grave);
            }
          }}
          onMouseEnter={(e) => {
            if (!isDisabled) {
              onGraveMouseEnter(grave, e);
            }
          }}
          onMouseLeave={() => {
            onGraveMouseLeave();
          }}
          onContextMenu={(e) => {
            if (!isDisabled) {
              e.preventDefault();
              handleGraveSelect(row, column);
            }
          }}
        >
          <span className="grave-id">{grave.id}</span>
          {grave.name && <span className="grave-name">{grave.name}</span>}
          {isDisabled && <span className="disabled-indicator">DISABLED</span>}
        </div>
      );
    } else {
      return (
        <div
          key={`${row}-${column}`}
          className="grave-cell empty"
          onClick={() => handleGraveClick(row, column)}
          onContextMenu={(e) => {
            e.preventDefault();
            handleGraveSelect(row, column);
          }}
          title={`${garden.name.split(' ')[1]}-${row}-${column} - Not created`}
        >
          <span className="grave-id">{garden.name.split(' ')[1]}-{row}-{column}</span>
        </div>
      );
    }
  };

  return (
    <div className="grave-grid">
      <div className="grid-header">
        <div className="column-labels">
          {Array.from({ length: garden.columns }, (_, i) => (
            <div key={i} className="column-label">{i + 1}</div>
          ))}
        </div>
      </div>
      
      <div className="grid-body">
        {Array.from({ length: garden.rows }, (_, row) => (
          <div key={row} className="grid-row">
            <div className="row-label">{row + 1}</div>
            <div className="row-graves">
              {Array.from({ length: garden.columns }, (_, column) => 
                renderGrave(row + 1, column + 1)
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
