import React, { useEffect, useState } from 'react';
import axios from 'axios';
import MapboxMap from '../components/MapboxMap';
import GraveLocator from '../components/GraveLocator';
import './MapboxGuestMapView.css';

export default function MapboxGuestMapView() {
  const [lots, setLots] = useState([]);
  const [selectedLot, setSelectedLot] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all'); // all, available, reserved, occupied

  // Add error timeout cleanup
  useEffect(() => {
    let errorTimeout;
    if (error) {
      errorTimeout = setTimeout(() => {
        setError(null);
      }, 5000);
    }
    return () => {
      if (errorTimeout) {
        clearTimeout(errorTimeout);
      }
    };
  }, [error]);

  // Fetch graves from backend (public endpoint)
  // Garden polygon coordinates (exact from your GeoJSON data)
  const gardenPolygons = {
    'A': [
      [121.069415, 14.53879],
      [121.069888, 14.538776],
      [121.069876, 14.538393],
      [121.069403, 14.538394],
      [121.069415, 14.53879] // Close the polygon
    ],
    'B': [
      [121.069928, 14.538777],
      [121.070611, 14.538762],
      [121.070609, 14.538391],
      [121.069919, 14.53839],
      [121.069928, 14.538777] // Close the polygon
    ],
    'C': [
      [121.070769, 14.538362],
      [121.071787, 14.538341],
      [121.07189, 14.538103],
      [121.070762, 14.53812],
      [121.070769, 14.538362] // Close the polygon
    ]
  };

  // Point-in-polygon test using ray casting algorithm
  const pointInPolygon = (point, polygon) => {
    const [x, y] = point;
    let inside = false;
    
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      const [xi, yi] = polygon[i];
      const [xj, yj] = polygon[j];
      
      if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) {
        inside = !inside;
      }
    }
    
    return inside;
  };

  // Filter graves that are outside garden polygon
  const filterGravesWithinBounds = (graves, garden) => {
    const polygon = gardenPolygons[garden];
    if (!polygon) return graves;
    
    // Calculate garden bounds for positioning
    const minLng = Math.min(...polygon.map(p => p[0]));
    const maxLng = Math.max(...polygon.map(p => p[0]));
    const minLat = Math.min(...polygon.map(p => p[1]));
    const maxLat = Math.max(...polygon.map(p => p[1]));
    
    const gardenWidth = maxLng - minLng;
    const gardenHeight = maxLat - minLat;
    
    // Real standard grave dimensions (1m × 2m)
    const standardGraveWidth = 0.00000465; // 1m in degrees longitude
    const standardGraveLength = 0.000009;  // 2m in degrees latitude
    
    // Calculate how many graves can fit with standard size
    const maxColumns = Math.floor(gardenWidth / standardGraveWidth);
    const maxRows = Math.floor(gardenHeight / standardGraveLength);
    
    // Use the actual data range to calculate grave size
    const actualRows = Math.max(...graves.map(g => g.row || 0));
    const actualColumns = Math.max(...graves.map(g => g.column || 0));
    const usedRows = Math.min(actualRows, maxRows);
    const usedColumns = Math.min(actualColumns, maxColumns);
    
    const actualGraveWidth = gardenWidth / usedColumns;
    const actualGraveLength = gardenHeight / usedRows;
    
    return graves.filter(grave => {
      const row = grave.row;
      const column = grave.column;
      
      if (!row || !column) return false;
      
      // Calculate grave center position
      const offsetLng = (column - 1) * actualGraveWidth;
      const offsetLat = (row - 1) * actualGraveLength;
      
      const graveCenterLng = minLng + offsetLng + (actualGraveWidth / 2);
      const graveCenterLat = minLat + offsetLat + (actualGraveLength / 2);
      
      // Check if the grave center is within the garden polygon
      const isWithinPolygon = pointInPolygon([graveCenterLng, graveCenterLat], polygon);
      
      if (!isWithinPolygon) {
        console.warn(`Grave ${grave.id} (row ${row}, col ${column}) is outside garden ${garden} polygon - HIDING`);
      }
      
      return isWithinPolygon;
    });
  };

  const fetchLots = async () => {
    try {
      setLoading(true);
      const allGraves = [];
      
      // Fetch graves from all three gardens using public endpoint
      const gardens = ['A', 'B', 'C'];
      for (const garden of gardens) {
        try {
          // For now, we'll use the public lots endpoint and filter for graves
          // TODO: Create a dedicated public graves endpoint
      const response = await axios.get(
        `${process.env.REACT_APP_API_URL}/public/lots`
      );
      
          // Filter for graves in this garden and convert to map format
          const gardenGraves = response.data
            .filter(lot => lot.id && lot.id.startsWith(`${garden}-`))
            .map(grave => ({
              _id: grave._id,
              id: grave.id,
              name: grave.name || '',
              birth: grave.birth || '',
              death: grave.death || '',
              status: grave.status,
              // Keep the original coordinates structure for rectangle rendering
              coordinates: grave.coordinates,
              // Add grave-specific data
              garden: grave.garden || garden,
              row: grave.row,
              column: grave.column,
              location: grave.location || `Garden ${garden}`,
              price: grave.price || 8000,
              sqm: grave.sqm || 2.0,
              // Keep bounds for backward compatibility with popup positioning
              bounds: grave.coordinates ? [
                [grave.coordinates.coordinates[1] - 0.000009, grave.coordinates.coordinates[0] - 0.00000465], // [lat, lng] - southwest
                [grave.coordinates.coordinates[1] + 0.000009, grave.coordinates.coordinates[0] + 0.00000465]  // [lat, lng] - northeast
              ] : grave.bounds || [[0, 0], [0, 0]]
            }));
          
          // Filter out graves that are outside garden bounds
          const filteredGardenGraves = filterGravesWithinBounds(gardenGraves, garden);
          console.log(`Garden ${garden}: ${gardenGraves.length} total graves, ${filteredGardenGraves.length} within bounds`);
          
          allGraves.push(...filteredGardenGraves);
        } catch (gardenErr) {
          console.warn(`Failed to fetch graves from Garden ${garden}:`, gardenErr);
        }
      }
      
      setLots(allGraves);
      setLoading(false);
    } catch (err) {
      console.error('Failed to fetch graves:', err);
      setError('Failed to load graves from server');
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLots();
  }, []);

  const handleLotClick = (lot) => {
    setSelectedLot(lot);
  };

  // Filter lots based on selected filter
  const filteredLots = lots.filter(lot => {
    if (filter === 'all') return true;
    return lot.status === filter;
  });

  const handleFilterChange = (newFilter) => {
    setFilter(newFilter);
    setSelectedLot(null); // Clear selection when changing filter
  };

  if (loading) {
    return (
      <div className="mapbox-guest-map-view loading">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Loading cemetery map...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mapbox-guest-map-view guest-map-bottom-spacing">
      {/* Header */}
      <div className="map-header">
        <div className="map-title">
          <h2>Cemetery Map</h2>
          <p>Explore our beautiful cemetery grounds and available lots</p>
        </div>
        
      </div>

      {/* Error message */}
      {error && (
        <div className="error-message">
          <span>⚠️ {error}</span>
          <button onClick={() => setError(null)}>×</button>
        </div>
      )}

      {/* Filter controls */}
      <div className="filter-controls">
        <div className="filter-buttons">
          <button
            className={`filter-btn ${filter === 'all' ? 'active' : ''}`}
            onClick={() => handleFilterChange('all')}
          >
            All Graves
          </button>
          <button
            className={`filter-btn ${filter === 'available' ? 'active' : ''}`}
            onClick={() => handleFilterChange('available')}
          >
            Available
          </button>
          <button
            className={`filter-btn ${filter === 'reserved' ? 'active' : ''}`}
            onClick={() => handleFilterChange('reserved')}
          >
            Reserved
          </button>
          <button
            className={`filter-btn ${filter === 'occupied' ? 'active' : ''}`}
            onClick={() => handleFilterChange('occupied')}
          >
            Occupied
          </button>
        </div>
        
        <div className="filter-info">
          Showing {filteredLots.length} of {lots.length} graves
        </div>
      </div>

      {/* Map container */}
      <div className="map-container">
        <MapboxMap
          lots={filteredLots}
          selectedLot={selectedLot}
          onLotClick={handleLotClick}
          onMapClick={() => {}} // No map click functionality for guests
          onLotCreate={() => {}} // No lot creation for guests
          isEditing={false} // Guests can't edit
          showRoads={true}
          showColumbarium={true}
        />
        
        {/* Grave Locator Overlay */}
        <div className="grave-locator-overlay">
          <GraveLocator
            lots={lots}
            onSelect={(lot) => {
              setSelectedLot(lot);
            }}
            onNavigate={(startLot, endLot) => {
              console.log('Navigate from', startLot, 'to', endLot);
            }}
          />
        </div>
      </div>

      {/* Statistics panel */}

      {/* Lot details panel */}
      {selectedLot && (
        <div className="lot-details-panel">
          <div className="lot-details-header">
            <h3>{selectedLot.block} {selectedLot.lotNumber}</h3>
            <button 
              className="close-btn"
              onClick={() => setSelectedLot(null)}
            >
              ×
            </button>
          </div>
          
          <div className="lot-details-content">
            <div className="detail-row">
              <span className="detail-label">Status:</span>
              <span className={`detail-value status-${selectedLot.status}`}>
                {selectedLot.status.charAt(0).toUpperCase() + selectedLot.status.slice(1)}
              </span>
            </div>
            
            {selectedLot.type && (
              <div className="detail-row">
                <span className="detail-label">Type:</span>
                <span className="detail-value">{selectedLot.type}</span>
              </div>
            )}
            
            {selectedLot.name && (
              <div className="detail-row">
                <span className="detail-label">Name:</span>
                <span className="detail-value">{selectedLot.name}</span>
              </div>
            )}
            
            {selectedLot.sqm && (
              <div className="detail-row">
                <span className="detail-label">Size:</span>
                <span className="detail-value">{selectedLot.sqm} sqm</span>
              </div>
            )}
            
            {selectedLot.price && (
              <div className="detail-row">
                <span className="detail-label">Price:</span>
                <span className="detail-value">₱{parseInt(selectedLot.price).toLocaleString()}</span>
              </div>
            )}
            
            {selectedLot.location && (
              <div className="detail-row">
                <span className="detail-label">Location:</span>
                <span className="detail-value">{selectedLot.location}</span>
              </div>
            )}
          </div>
          
          {/* Call to action for guests */}
          <div className="guest-cta">
            <p>Interested in this lot? Contact us for more information!</p>
            <div className="cta-buttons">
              <button className="cta-btn primary">
                📞 Contact Us
              </button>
              <button className="cta-btn secondary">
                📋 Get Information
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Bottom spacing div */}
      <div style={{ height: '32px', backgroundColor: '#f8f9fa' }}></div>
    </div>
  );
}

